<?php
namespace Modules\Cutting\Http\Controllers;
use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Modules\Cutting\Models\CutOrder;use Modules\Cutting\Models\CutOutput;use Modules\Cutting\Models\Lay;use Modules\Cutting\Models\ShadeOverrideRequest;use Modules\Cutting\Services\LayExecutionService;use Modules\MasterData\Models\Customer;use Modules\Receiving\Models\FabricRoll;use RuntimeException;
class LayController extends Controller { public function __construct(private LayExecutionService $service){} public function buyerRule(Request$r,Customer$c):JsonResponse{return$this->domain(fn()=>response()->json($this->service->buyerRule($c,$r->user())));} public function configureBuyer(Request$r,Customer$c):JsonResponse{$d=$r->validate(['enabled'=>'required|boolean']);return$this->domain(fn()=>response()->json($this->service->configureBuyer($c,(bool)$d['enabled'],$r->user())));} public function index(Request$r,CutOrder$co):JsonResponse{return$this->domain(fn()=>response()->json(['data'=>$this->service->list($co,$r->user())]));} public function store(Request$r,CutOrder$co):JsonResponse{$d=$r->validate(['layer_count'=>'required|integer|min:1']);return$this->domain(fn()=>response()->json($this->service->createLay($co,(int)$d['layer_count'],$r->user()),201));} public function addRoll(Request$r,Lay$l):JsonResponse{$d=$r->validate(['fabric_roll_id'=>'required|integer','qty_used'=>'required|numeric|gt:0']);$roll=FabricRoll::withoutGlobalScopes()->findOrFail($d['fabric_roll_id']);return$this->domain(fn()=>response()->json($this->service->addRoll($l,$roll,(float)$d['qty_used'],$r->user()),201));} public function requestOverride(Request$r,Lay$l):JsonResponse{$d=$r->validate(['fabric_roll_id'=>'required|integer','qty_used'=>'required|numeric|gt:0','reason'=>'required|string|min:3']);$roll=FabricRoll::withoutGlobalScopes()->findOrFail($d['fabric_roll_id']);return$this->domain(fn()=>response()->json($this->service->requestOverride($l,$roll,(float)$d['qty_used'],$d['reason'],$r->user()),201));} public function applyOverride(Request$r,ShadeOverrideRequest$o):JsonResponse{return$this->domain(fn()=>response()->json($this->service->applyOverride($o,$r->user()),201));} public function output(Request$r,Lay$l):JsonResponse{$d=$r->validate(['cut_order_line_id'=>'required|integer','qty_cut'=>'required|numeric|gt:0']);return$this->domain(fn()=>response()->json($this->service->createOutput($l,(int)$d['cut_order_line_id'],(float)$d['qty_cut'],$r->user()),201));} public function bundles(Request$r,CutOutput$o):JsonResponse{$d=$r->validate(['bundle_size'=>'required|integer|min:1']);return$this->domain(fn()=>response()->json(['data'=>$this->service->generateBundles($o,(int)$d['bundle_size'],$r->user())],201));} public function complete(Request$r,Lay$l):JsonResponse{return$this->domain(fn()=>response()->json($this->service->completeLay($l,$r->user())));} private function domain(callable$f):JsonResponse{try{return$f();}catch(RuntimeException$e){return response()->json(['message'=>$e->getMessage()],422);}} }
